/**
 * Injects the Stilltime home-screen widget into the generated Android project.
 *
 * Copies `android-widget/**` into `android/app/src/main/`, rewriting the package
 * token, and registers the AppWidgetProvider plus its configuration activity in
 * the manifest. The tracked source of truth is `android-widget/`; `android/` is
 * regenerated by `bun run prebuild` and is git-ignored.
 *
 * CommonJS on purpose: see the note in `./gradleReference.js`.
 */

'use strict';

const fs = require('node:fs');
const path = require('node:path');

const {
  AndroidConfig,
  createRunOncePlugin,
  withAndroidManifest,
  withDangerousMod,
} = require('expo/config-plugins');

const {
  WIDGET_INFO_XML_RESOURCE,
  WIDGET_PACKAGE_SUFFIX,
  widgetActionConstants,
  widgetComponent,
} = require('./widgetTemplate');

const SOURCE_ROOT = path.resolve(__dirname, '..', 'android-widget');

/**
 * Placeholder replaced with the real application id when widget sources are
 * copied into the generated app module. The widget needs the app's own `R`
 * class and the application id is configurable, so the sources cannot import it
 * literally.
 */
const PACKAGE_TOKEN = '__STILLTIME_APP_PACKAGE__';

const TEXT_EXTENSIONS = new Set(['.kt', '.java', '.xml']);

/**
 * @param {string} root
 * @returns {string[]}
 */
function listFilesRecursive(root) {
  if (!fs.existsSync(root)) return [];
  const out = [];
  const walk = (dir, rel) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const abs = path.join(dir, entry.name);
      const relPath = rel.length > 0 ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) walk(abs, relPath);
      else out.push(relPath);
    }
  };
  walk(root, '');
  return out;
}

/**
 * @param {string} contents
 * @param {string} appPackage
 */
function renderSource(contents, appPackage) {
  return contents.split(PACKAGE_TOKEN).join(appPackage);
}

/** @param {{ android?: { package?: string } }} config */
function resolveAppPackage(config) {
  const fromConfig = config.android?.package;
  if (typeof fromConfig === 'string' && fromConfig.length > 0) return fromConfig;
  throw new Error('[stilltime] android.package must be set for the widget plugin to place sources.');
}

/** Renders `<intent-filter><action android:name="..."/></intent-filter>`. */
function actionFilter(actionName) {
  return { action: [{ $: { 'android:name': actionName } }] };
}

const withStilltimeAndroid = createRunOncePlugin(
  (config) => {
    const appPackage = resolveAppPackage(config);
    const widgetPackage = `${appPackage}.${WIDGET_PACKAGE_SUFFIX}`;

    // -----------------------------------------------------------------
    // Manifest: permission + receivers
    // -----------------------------------------------------------------
    const withManifest = withAndroidManifest(config, (cfg) => {
      // The only permission Stilltime needs. Required by
      // Settings.System.canWrite() and Settings.System.putInt().
      //
      // Stilltime is fully offline: INTERNET and ACCESS_NETWORK_STATE are
      // intentionally NOT requested, and the widget uses RemoteViews rather
      // than a RemoteViewsService so no collection permission is needed.
      AndroidConfig.Permissions.addPermission(
        cfg.modResults,
        'android.permission.WRITE_SETTINGS',
      );

      const manifest = cfg.modResults.manifest;
      manifest.$ = manifest.$ ?? {};
      manifest.$['xmlns:android'] = 'http://schemas.android.com/apk/res/android';

      const application = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults);

      const providerMetadata = {
        $: {
          'android:name': 'android.appwidget.provider',
          'android:resource': WIDGET_INFO_XML_RESOURCE,
        },
      };

      application.activity = [
        ...(application.activity ?? []),
        {
          $: {
            'android:name': `.${WIDGET_PACKAGE_SUFFIX}.${widgetComponent.configurationActivityClassName}`,
            'android:exported': 'true',
            'android:theme': '@android:style/Theme.Translucent.NoTitleBar',
          },
          'intent-filter': [actionFilter('android.appwidget.action.APPWIDGET_CONFIGURE')],
          'meta-data': [providerMetadata],
        },
      ];

      application.receiver = [
        ...(application.receiver ?? []),
        {
          $: {
            'android:name': `.${WIDGET_PACKAGE_SUFFIX}.${widgetComponent.className}`,
            'android:exported': 'true',
          },
          'intent-filter': [
            actionFilter('android.appwidget.action.APPWIDGET_UPDATE'),
            actionFilter(widgetActionConstants.actionApply),
            actionFilter(widgetActionConstants.actionToggleStayAwake),
            actionFilter(widgetActionConstants.actionRefresh),
          ],
          'meta-data': [providerMetadata],
        },
      ];

      return cfg;
    });

    // -----------------------------------------------------------------
    // Sources + resources copied into the generated app module
    // -----------------------------------------------------------------
    const withSources = withDangerousMod(withManifest, [
      'android',
      async (cfg) => {
        if (!fs.existsSync(SOURCE_ROOT)) {
          throw new Error(`[stilltime] Widget source directory missing: ${SOURCE_ROOT}`);
        }

        const appMainDir = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'main');
        fs.mkdirSync(appMainDir, { recursive: true });

        let copied = 0;

        // Kotlin sources land in conventional nested package directories.
        const kotlinOut = path.join(appMainDir, 'java', ...widgetPackage.split('.'));
        for (const relative of listFilesRecursive(path.join(SOURCE_ROOT, 'kotlin'))) {
          const destination = path.join(kotlinOut, path.basename(relative));
          fs.mkdirSync(path.dirname(destination), { recursive: true });
          fs.writeFileSync(
            destination,
            renderSource(fs.readFileSync(path.join(SOURCE_ROOT, 'kotlin', relative), 'utf8'), appPackage),
            'utf8',
          );
          copied += 1;
        }

        // Resources keep their directory structure (res/layout, res/xml, ...).
        const resRoot = path.join(SOURCE_ROOT, 'res');
        for (const relative of listFilesRecursive(resRoot)) {
          const source = path.join(resRoot, relative);
          const destination = path.join(appMainDir, 'res', relative);
          fs.mkdirSync(path.dirname(destination), { recursive: true });

          if (TEXT_EXTENSIONS.has(path.extname(relative))) {
            fs.writeFileSync(destination, renderSource(fs.readFileSync(source, 'utf8'), appPackage), 'utf8');
          } else {
            fs.copyFileSync(source, destination);
          }
          copied += 1;
        }

        fs.writeFileSync(
          path.join(kotlinOut, 'WIDGET_SOURCES.txt'),
          [
            'Generated by `plugins/withStilltimeAndroid.js` from the tracked',
            '`android-widget/` directory during `expo prebuild`.',
            '',
            '`android/` is git-ignored and fully regenerated. Edit `android-widget/`.',
            '',
          ].join('\n'),
          'utf8',
        );

        console.log(
          `[stilltime] Injected ${copied} widget source/resource file(s) into the app module.`,
        );
        return cfg;
      },
    ]);

    return withSources;
  },
  'withStilltimeAndroid',
  '1.0.0',
);

module.exports = withStilltimeAndroid;
module.exports.default = withStilltimeAndroid;
module.exports.PACKAGE_TOKEN = PACKAGE_TOKEN;
module.exports.WIDGET_PACKAGE_SUFFIX = WIDGET_PACKAGE_SUFFIX;
module.exports.widgetActionConstants = widgetActionConstants;
module.exports.widgetComponent = widgetComponent;